class RunningMedian:
    def __init__(self):
        self.lower_half = []  # max-heap (inverted using negative values)
        self.upper_half = []  # min-heap

    def add(self, x: float) -> None:
        if not self.lower_half or x <= -self.lower_half[0]:
            bisect.insort(self.lower_half, -x)
        else:
            bisect.insort(self.upper_half, x)

        # Balance the heaps
        if len(self.lower_half) > len(self.upper_half) + 1:
            val = -self.lower_half.pop()
            bisect.insort(self.upper_half, val)
        elif len(self.upper_half) > len(self.lower_half):
            val = self.upper_half.pop(0)
            bisect.insort(self.lower_half, -val)

    def median(self) -> float:
        if (len(self.lower_half) + len(self.upper_half)) % 2 == 1:
            return -self.lower_half[0]
        else:
            return (-self.lower_half[0] + self.upper_half[0]) / 2
